list_tax_codes.code:
import (
	"fmt"
)

resp, err := client.TaxCodes().ListTaxCodes(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["tax_codes"].([]any) {
	taxCode := row.(map[string]any)
	fmt.Println(taxCode["id"], taxCode["name"], taxCode["rate"])
}

